package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The sheet's "today". Every date decision and every default date in the app reads the date from
 * here, never from the real clock. A sheet starts at the real date until its today is set.
 */
@Service
public class SheetClock {

    private final JdbcTemplate jdbc;

    public SheetClock(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public LocalDate today(String sheet) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getDate(1).toLocalDate(), sheet);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheet, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheet, Date.valueOf(today));
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import net.officefloor.hq.app.Audit;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The people each user watches on a sheet, kept in the order they started watching. */
@Repository
public class Watches {

    private final JdbcTemplate jdbc;
    private final Audit audit;

    public Watches(JdbcTemplate jdbc, Audit audit) {
        this.jdbc = jdbc;
        this.audit = audit;
    }

    /** The ids of the people the user watches on the sheet. */
    public List<Long> watchedBy(String sheet, String user) {
        return jdbc.queryForList("SELECT person_id FROM watch WHERE sheet = ? AND user_name = ? ORDER BY id",
                Long.class, sheet, user);
    }

    /** The users watching the person, in the order they started watching. */
    public List<String> watchers(String sheet, long person) {
        return jdbc.queryForList("SELECT user_name FROM watch WHERE sheet = ? AND person_id = ? ORDER BY id",
